<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3'; import InventoryNav from '../../Components/Common/InventoryNav.vue';
interface Account{id:number;code:string;name:string;type:string;active:boolean;accepts_entries:boolean} interface Period{id:number;year:number;month:number;starts_on:string;ends_on:string;status:string} interface Entry{id:number;number:string;entry_date:string;description:string;reference:string|null;source_type:string} interface Balance{id:number;code:string;name:string;type:string;debit:string;credit:string} interface Statements{debits:string;credits:string;difference:string;revenue:string;expenses:string;profit:string;assets:string;liabilities:string;equity:string;equation_difference:string}
defineProps<{filters:{from:string;to:string};accounts:Account[];periods:Period[];entries:Entry[];trialBalance:Balance[];statements:Statements}>();
const account=useForm({code:'',name:'',type:'asset',parent_id:'',accepts_entries:true});const period=useForm({year:new Date().getFullYear(),month:new Date().getMonth()+1,starts_on:new Date().toISOString().slice(0,8)+'01',ends_on:''});type Line={account_id:number|string;description:string;debit:number;credit:number};const journal=useForm({entry_date:new Date().toISOString().slice(0,10),description:'',reference:'',lines:[{account_id:'',description:'',debit:0,credit:0},{account_id:'',description:'',debit:0,credit:0}] as Line[]});
const saveAccount=()=>account.post('/accounting/accounts',{onSuccess:()=>account.reset()});const savePeriod=()=>period.post('/accounting/periods',{onSuccess:()=>period.reset()});const addLine=()=>journal.lines.push({account_id:'',description:'',debit:0,credit:0});const postJournal=()=>journal.post('/accounting/journal',{onSuccess:()=>journal.reset()});const close=(p:Period)=>{if(confirm(`¿Cerrar ${p.month}/${p.year}?`))router.patch(`/accounting/periods/${p.id}/close`,{},{preserveScroll:true})};const filter=(e:Event)=>{const d=new FormData(e.target as HTMLFormElement);router.get('/accounting',{from:String(d.get('from')),to:String(d.get('to'))},{preserveState:true})};
</script>
<template><Head title="Contabilidad"/><main class="page"><InventoryNav/><h1>Contabilidad empresarial</h1><p>Plan de cuentas, períodos, diario, estados financieros y comprobación de partida doble.</p><section class="statement-cards"><article><small>Débitos / créditos</small><strong>{{Number(statements.debits).toFixed(2)}} / {{Number(statements.credits).toFixed(2)}}</strong><span :class="Number(statements.difference)===0?'ok':'bad'">{{Number(statements.difference)===0?'Libro cuadrado':'Diferencia '+statements.difference}}</span></article><article><small>Ingresos del período</small><strong>{{Number(statements.revenue).toFixed(2)}}</strong><span>Ventas e ingresos contabilizados</span></article><article><small>Gastos y costos</small><strong>{{Number(statements.expenses).toFixed(2)}}</strong><span>Incluye costo de ventas y gastos</span></article><article><small>Resultado</small><strong>{{Number(statements.profit).toFixed(2)}}</strong><span :class="Number(statements.profit)>=0?'ok':'bad'">{{Number(statements.profit)>=0?'Utilidad':'Pérdida'}}</span></article></section><div class="columns"><form class="card form" @submit.prevent="saveAccount"><h2>Nueva cuenta</h2><label>Código<input v-model="account.code" required></label><label>Nombre<input v-model="account.name" required></label><label>Tipo<select v-model="account.type"><option value="asset">Activo</option><option value="liability">Pasivo</option><option value="equity">Patrimonio</option><option value="revenue">Ingreso</option><option value="expense">Gasto</option></select></label><label class="check"><input v-model="account.accepts_entries" type="checkbox">Acepta movimientos</label><button>Guardar cuenta</button></form><form class="card form" @submit.prevent="savePeriod"><h2>Nuevo período</h2><label>Año<input v-model.number="period.year" type="number" required></label><label>Mes<input v-model.number="period.month" type="number" min="1" max="12" required></label><label>Desde<input v-model="period.starts_on" type="date" required></label><label>Hasta<input v-model="period.ends_on" type="date" required></label><button>Abrir período</button></form></div><section class="card table"><h2>Plan de cuentas</h2><table><thead><tr><th>Código</th><th>Cuenta</th><th>Tipo</th><th>Movimientos</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td>{{a.code}}</td><td>{{a.name}}</td><td>{{a.type}}</td><td>{{a.accepts_entries?'Sí':'No'}}</td></tr></tbody></table><h2>Períodos</h2><table><tbody><tr v-for="p in periods" :key="p.id"><td>{{p.month}}/{{p.year}}</td><td>{{p.starts_on}} — {{p.ends_on}}</td><td>{{p.status==='open'?'Abierto':'Cerrado'}}</td><td><button v-if="p.status==='open'" class="danger" @click="close(p)">Cerrar</button></td></tr></tbody></table></section><form class="card" @submit.prevent="postJournal"><h2>Asiento manual</h2><div class="header"><label>Fecha<input v-model="journal.entry_date" type="date" required></label><label>Descripción<input v-model="journal.description" required></label><label>Referencia<input v-model="journal.reference"></label></div><div v-for="(l,i) in journal.lines" :key="i" class="line"><select v-model="l.account_id" required><option value="">Cuenta</option><option v-for="a in accounts.filter(x=>x.active&&x.accepts_entries)" :key="a.id" :value="a.id">{{a.code}} — {{a.name}}</option></select><input v-model="l.description" placeholder="Detalle"><input v-model.number="l.debit" type="number" min="0" step=".01" placeholder="Débito"><input v-model.number="l.credit" type="number" min="0" step=".01" placeholder="Crédito"></div><button type="button" class="secondary" @click="addLine">+ Línea</button> <button>Publicar asiento</button><p class="error">{{Object.values(journal.errors)[0]}}</p></form><section class="card"><form class="filters" @submit.prevent="filter"><label>Desde<input name="from" type="date" :value="filters.from"></label><label>Hasta<input name="to" type="date" :value="filters.to"></label><button>Consultar</button></form><h2>Balance de comprobación</h2><div class="table"><table><thead><tr><th>Código</th><th>Cuenta</th><th>Débito</th><th>Crédito</th><th>Saldo</th></tr></thead><tbody><tr v-for="b in trialBalance" :key="b.id"><td>{{b.code}}</td><td>{{b.name}}</td><td>{{Number(b.debit).toFixed(2)}}</td><td>{{Number(b.credit).toFixed(2)}}</td><td>{{(Number(b.debit)-Number(b.credit)).toFixed(2)}}</td></tr></tbody></table></div><h2>Libro diario</h2><div class="table"><table><thead><tr><th>Número</th><th>Fecha</th><th>Descripción</th><th>Origen</th><th>Referencia</th></tr></thead><tbody><tr v-for="e in entries" :key="e.id"><td>{{e.number}}</td><td>{{e.entry_date}}</td><td>{{e.description}}</td><td>{{e.source_type}}</td><td>{{e.reference||'—'}}</td></tr></tbody></table></div></section></main></template>
<style scoped>.page{max-width:1500px;margin:auto;padding:2rem}.statement-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;margin:1rem 0}.statement-cards article{display:grid;gap:.35rem;padding:1rem;border:1px solid var(--p-content-border-color);border-radius:.8rem;background:var(--p-content-background)}.statement-cards strong{font-size:1.25rem}.statement-cards small,.statement-cards span{color:var(--p-text-muted-color)}.statement-cards .ok{color:#16a34a}.statement-cards .bad{color:#dc2626}.columns{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.card{padding:1.5rem;border:1px solid var(--p-content-border-color);border-radius:1rem;margin:1rem 0;background:var(--p-content-background)}.form,.header,.filters{display:flex;gap:1rem;flex-wrap:wrap}.line{display:grid;grid-template-columns:2fr 2fr 1fr 1fr;gap:.7rem;margin:.7rem 0}label{display:grid;gap:.3rem;font-weight:600}.check{display:flex;align-items:center}input,select{padding:.7rem;border:1px solid var(--p-content-border-color);border-radius:.5rem;background:transparent;color:inherit}button{padding:.65rem .9rem;border:0;border-radius:.5rem;background:var(--p-primary-color);color:var(--p-primary-contrast-color);font-weight:700}.secondary{background:transparent;color:inherit;border:1px solid var(--p-content-border-color)}.danger{background:#ef4444}.table{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:.7rem;border-bottom:1px solid var(--p-content-border-color);text-align:left}.error{color:#ef4444}@media(max-width:1000px){.statement-cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:850px){.columns,.statement-cards{grid-template-columns:1fr}.line{grid-template-columns:1fr 1fr}.page{padding:1rem}}</style>
